// Regenerates the embedded TS copy of every pack (browser bundles have no fs): packages/haunt/src/packs/embedded.ts.
// Every folder under packs/ that holds a pack.yaml is embedded, so a new pack (haunt pack new <id>) needs no hand edit anywhere.
// Usage: npm run packs:embed            rewrite the copy
//        npm run packs:embed -- --check exit 1 when the copy has drifted (never hand edit the generated file)
import { readFileSync, writeFileSync, existsSync, readdirSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));

export function renderEmbedded(packs) {
  const body = Object.entries(packs).map(([id, text]) => `  ${JSON.stringify(id)}: ${JSON.stringify(text.split('\r\n').join('\n'))},`).join('\n');
  return `// GENERATED by tools/embed-packs.mjs from packs/*/pack.yaml. Do not edit: run \`npm run packs:embed\`.\n` +
    `// A drift test fails when this copy differs from the pack files.\n` +
    `export const EMBEDDED_PACKS: Readonly<Record<string, string>> = {\n${body}\n};\n`;
}

export function readPacks(base = root) {
  const dir = resolve(base, 'packs');
  const out = {};
  if (!existsSync(dir)) return out;
  for (const d of readdirSync(dir, { withFileTypes: true }).filter((x) => x.isDirectory()).map((x) => x.name).sort()) {
    const f = resolve(dir, d, 'pack.yaml');
    if (existsSync(f)) out[d] = readFileSync(f, 'utf8');
  }
  return out;
}

/** Returns the files that were (or, with check, would be) rewritten. */
export function embedPacks({ check = false, base = root } = {}) {
  const out = resolve(base, 'packages/haunt/src/packs/embedded.ts');
  const want = renderEmbedded(readPacks(base));
  const have = existsSync(out) ? readFileSync(out, 'utf8') : '';
  if (have === want) return [];
  if (!check) writeFileSync(out, want);
  return [out];
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const check = process.argv.includes('--check');
  const changed = embedPacks({ check });
  if (check && changed.length) { console.error('embedded packs are out of date; run: npm run packs:embed'); process.exit(1); }
  console.log(changed.length ? 'rewrote packages/haunt/src/packs/embedded.ts' : 'embedded packs are up to date');
}
